import {KEY,PLANS,SEQUENCES,initial,loadState,serialize,reduce,activeDevice,matchVoice,extendState} from './demo-store.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=loadState(localStorage.getItem(KEY))}catch{state=initial()}
const pages={dashboard:['Visão geral','Seu cuidado, <em>em foco.</em>','Explore a proteção de um dispositivo fictício. Nenhuma ação altera seu celular real.'],voice:['Comandos de voz','Uma palavra.<br><em>Uma resposta.</em>','Configure e teste frases por texto. O microfone permanece desligado.'],physical:['Acionamentos','Seu gesto.<br><em>Sua escolha.</em>','Selecione uma sequência demonstrativa. Botões físicos reais dependem do sistema.'],location:['Localização','Um caminho<br><em>de volta.</em>','Posições fictícias em um mapa ilustrativo. Nenhum GPS do visitante é acessado.'],lost:['Celular perdido','Este celular<br><em>tem um lar.</em>','Uma mensagem e um contato fictícios ajudam a apresentar o modo perdido.'],contacts:['Contatos','Sua rede<br><em>de confiança.</em>','Cadastre apenas pessoas fictícias. Validações e alertas são simulados.'],recovery:['Recuperação','Seu controle.<br><em>Seu próximo passo.</em>','A recuperação demonstrativa possui duas etapas. Voz isolada não autoriza ações reais.'],web:['Painel de recuperação','Distante do celular.<br><em>Perto do controle.</em>','Explore dispositivos, incidentes, mapa, comandos e atividades em um painel fictício.'],plans:['Assinatura','Para você.<br><em>Para quem importa.</em>','Compare, selecione e simule planos sem inserir dados de pagamento.'],profile:['Perfil e preferências','Familiar no toque.<br><em>Do seu jeito.</em>','Suas preferências demonstrativas ficam somente neste navegador.']};
Object.assign(pages,{onboarding:['Primeiros passos','Sua proteção,<br><em>passo a passo.</em>','Configure uma experiência fictícia. Nenhuma permissão real é solicitada.'],protection:['Proteção','Controle com <em>clareza.</em>','Conheça mecanismos, permissões e limites da plataforma.'],devices:['Dispositivos','Cada aparelho,<br><em>no seu lugar.</em>','Gerencie os dispositivos da sua conta demonstrativa.'],incidents:['Incidentes','Uma história<br><em>bem registrada.</em>','Eventos fictícios, ações e resultados, em um só lugar.'],notifications:['Notificações','O que merece<br><em>sua atenção.</em>','Alertas locais da demonstração; nenhuma entrega externa.'],help:['Ajuda e configurações','Entenda cada <em>detalhe.</em>','Diagnóstico, compatibilidade, privacidade e orientações.']});
state=extendState(state);
const labels={ACTIVE:'Proteção ativa',DISABLED:'Proteção desativada',EMERGENCY:'Emergência simulada',LOST:'Modo perdido',RECOVERING:'Recuperação em andamento',RESOLVED:'Emergência encerrada'};
const commandNames={LOCK:'Bloquear tela',LOST:'Modo perdido',RECOVER:'Recuperar acesso',ALARM:'Alarme',STOP_ALARM:'Silenciar'};
const protocol=['Comando de emergência reconhecido','Protocolo de proteção ativado','Tela bloqueada na simulação','Localização fictícia registrada','Alerta demonstrativo registrado','Painel de recuperação atualizado'];
let voiceTimer=null;
let page=Object.keys(pages).includes(location.hash.slice(1))?location.hash.slice(1):'dashboard',webTab='overview',simulationTimer=null,simulating=false,alarm=null,alarmContext=null,alarmTimeout=null,toastTimer=null,zoom=1,incidentFilter='ALL';
const date=t=>new Date(t).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}),isEmergency=d=>['EMERGENCY','LOST','RECOVERING'].includes(d.state),selectedIncident=()=>state.incidents.find(i=>i.deviceId===state.selectedDevice&&!i.closedAt),plan=()=>PLANS.find(p=>p.id===state.billing.plan);
function save(){try{localStorage.setItem(KEY,serialize(state))}catch{toast('Armazenamento local indisponível. As alterações duram apenas esta sessão.')}}
function act(action){state=reduce(state,action);save();render()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
$('#close').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal'))close()};
function stopSimulation(){clearTimeout(voiceTimer);voiceTimer=null;clearInterval(simulationTimer);simulationTimer=null;simulating=false}
function go(next){if(!pages[next])return;page=next;history.replaceState({},'',`#${next}`);$('#app aside').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'smooth'})}
function logHTML(items,empty='Nenhum registro ainda. Explore uma ação demonstrativa.'){return items.length?items.map(x=>`<div class="item"><strong>${esc(x.text||x.trigger||x.type)}</strong><small>${esc(date(x.at))}${x.closedAt?' · Encerrado':''}</small></div>`).join(''):`<div class="empty">${empty}</div>`}
function statusHTML(d){return `<span class="badge ${isEmergency(d)?'alert':''}">${esc(labels[d.state])}</span>`}
function phone(d=activeDevice(state),lost=false){return `<div class="phone"><div class="phone-inner"><div class="statusbar"><span>9:41</span><span>◈ SENTINELA · DEMO</span><span>▰</span></div><div class="center">${lost?'<div style="font-size:45px;color:var(--green);margin:35px 0">⌖</div><div class="eyebrow">APARELHO FICTÍCIO ENCONTRADO</div><h3>Este celular<br>tem um lar.</h3>':`<div class="shield-ring"><div class="shield ${isEmergency(d)?'alert':''}">${isEmergency(d)?'⌑':'✓'}</div></div><h3>${esc(labels[d.state])}.</h3>`}<p>${esc(lost?d.message:'Uma experiência de proteção, inteiramente simulada.')}</p>${lost?`<div class="item"><strong>${esc(d.contact)}</strong></div><p class="fine">Contato fictício. Nenhuma ligação será efetuada.</p><button class="outline full" data-action="found">Encontrei este aparelho</button>`:statusHTML(d)}<div class="phone-state"><span class="status-dot ${d.online?'':'off'}"></span>${d.online?'Conexão fictícia online':'Aparelho fictício offline'}</div></div></div></div>`}
function map(d=activeDevice(state)){const p=state.locations.find(l=>l.deviceId===d.id);return `<div class="map" style="background-size:${zoom*100}% ${zoom*100}%"><span class="map-label">CIDADE FICTÍCIA · MAPA ESQUEMÁTICO</span><button class="marker" aria-label="Ver dispositivo fictício" data-action="marker"></button><div class="map-popup">${esc(d.name)} · ${esc(p?.label||'Sem posição fictícia')}</div><div class="map-controls"><button aria-label="Diminuir mapa" data-action="zoomOut">−</button><button aria-label="Ampliar mapa" data-action="zoomIn">+</button><button aria-label="Centralizar mapa" data-action="centerMap">⌖</button></div></div>${p?`<div class="coords">${p.latitude.toFixed(6)}, ${p.longitude.toFixed(6)} · ±${p.accuracy} m<br>${esc(date(p.at))} · DADOS FICTÍCIOS${!d.online?' · Última posição conhecida':''}</div>`:'<p class="fine">Nenhuma posição registrada.</p>'}`}
function dashboard(){const d=activeDevice(state),i=selectedIncident();return `<div class="grid-three metrics"><div class="metric"><span>DISPOSITIVOS</span><b>${state.devices.length}</b><span>Todos fictícios</span></div><div class="metric"><span>INCIDENTES</span><b>${state.incidents.length}</b><span>Histórico demonstrativo</span></div><div class="metric"><span>CONTATOS</span><b>${state.contacts.length}</b><span>Sua rede simulada</span></div></div><div class="split"><div><div class="card soft"><div class="card-head"><h2>Presença que <em>tranquiliza.</em></h2>${statusHTML(d)}</div><p class="fine">Última sincronização fictícia: ${date(d.lastSync)} · Voz ${state.monitoring?'simulada ativa':'desligada'} · ${Object.values(d.permissions).filter(Boolean).length}/4 permissões fictícias<br>${esc(d.name)} · ${esc(d.platform)} · Nenhum controle real neste ambiente.</p><div class="actions"><button class="primary" data-action="protection" ${isEmergency(d)?'disabled':''}>${d.protected?'Desativar':'Ativar'} proteção</button><button class="danger" data-action="emergency" ${simulating?'disabled':''}>${i?'Continuar simulação':'Simular assalto'} ↗</button></div><div class="actions"><button class="outline" data-action="end" ${isEmergency(d)?'':'disabled'}>Encerrar emergência</button><button class="text" data-action="resetDevice">Reiniciar simulação</button></div>${isEmergency(d)?'<p class="danger-note">O estado de emergência deve ser encerrado explicitamente. Cancelar uma assinatura não desativa a proteção.</p>':''}</div><div class="card"><h3>Cada etapa, com clareza.</h3><ol class="protocol">${protocol.map((p,n)=>`<li class="${(i?.step||0)>n?'done':''}"><span>0${n+1}</span>${p}</li>`).join('')}</ol><p class="fine">Bloqueio, GPS e envio de alerta são representações visuais. Nada é enviado a contatos reais.</p></div></div><div>${phone(d)}<div class="card" style="margin-top:25px"><h3>Últimos eventos.</h3>${logHTML(state.activity.slice(0,4))}</div></div></div><div class="card"><h3>Explore o aplicativo.</h3><div class="pillset">${Object.entries(pages).filter(([k])=>k!=='dashboard').map(([k,p])=>`<button data-page="${k}">${p[0]} ↗</button>`).join('')}</div></div>`}
function voice(){return `<div class="card soft row wrap"><div><strong>Monitoramento ${state.monitoring?'simulado ativo':'encerrado'}</strong><p class="fine">Microfone real desligado. Teste de reconhecimento feito por texto.</p></div><button class="outline" data-extra="monitor">${state.monitoring?'Encerrar':'Iniciar'} monitoramento simulado</button></div><div class="grid"><div class="card"><div class="card-head"><h3>Frases de emergência.</h3><span class="badge">MICROFONE DESLIGADO</span></div>${state.commands.length?state.commands.map(v=>`<div class="item"><div class="row"><label class="check" style="margin:0"><input type="radio" name="voice" data-voice-select="${esc(v.id)}" ${state.selectedCommand===v.id?'checked':''}>${esc(v.phrase)}</label><div><button class="quiet" data-edit-voice="${esc(v.id)}">Editar</button><button class="quiet red" data-delete-voice="${esc(v.id)}">Excluir</button></div></div></div>`).join(''):'<p class="fine">Adicione uma frase antes de testar.</p>'}<form id="voiceAdd"><label for="voicePhrase">Nova frase demonstrativa</label><input id="voicePhrase" maxlength="50" required placeholder="Minha frase secreta"><div class="actions"><button class="primary" ${state.commands.length>=10?'disabled':''}>Adicionar comando</button></div></form><p class="fine" style="margin-top:18px">Até dez frases. Nenhuma escuta ou gravação acontece neste site.</p></div><div class="card soft"><h3>Teste com intenção.</h3><label for="sensitivity">Correspondência demonstrativa</label><select id="sensitivity"><option value="EXACT" ${state.sensitivity==='EXACT'?'selected':''}>Frase exata · mais restrita</option><option value="FLEX" ${state.sensitivity==='FLEX'?'selected':''}>Frase inteira na sentença</option></select><div class="wave" id="wave">${Array.from({length:35},(_,i)=>`<i style="--height:${9+Math.sin(i*.7)**2*32}px;--delay:${i*.03}s"></i>`).join('')}</div><form id="voiceTest"><label for="heard">Texto que o reconhecimento simulado ouviria</label><input id="heard" maxlength="100" required value="${esc(state.commands.find(v=>v.id===state.selectedCommand)?.phrase||'')}"><button class="primary full" style="margin-top:15px" ${state.commands.length?'':'disabled'}>Testar ativação simulada</button></form><p class="fine" style="margin-top:18px">No Android real, o reconhecimento local exige suporte do aparelho e permissão explícita. Não há promessa de escuta permanente.</p></div></div>`}
function physical(){const q=SEQUENCES.find(q=>q[0]===state.sequence);return `<div class="grid"><div class="card"><h3>Escolha sua sequência.</h3>${SEQUENCES.map(q=>`<label class="item check"><input type="radio" name="sequence" data-sequence="${q[0]}" ${state.sequence===q[0]?'checked':''}>${q[1]}</label>`).join('')}<div class="actions"><button class="primary" data-action="saveSequence">Salvar preferência</button></div><p class="fine" style="margin-top:20px">As escolhas ficam neste navegador e não interceptam botões físicos.</p></div><div class="card soft"><h3>Discreto por natureza.</h3><div class="sequence" id="sequence">${q?.[2]}</div><div class="actions"><button class="outline" data-action="animateSequence">Visualizar sequência</button><button class="primary" data-action="sequenceEmergency">Testar acionamento demonstrativo</button></div><p class="danger-note">Apps comuns não podem observar livremente Power ou substituir combinações do sistema. Atalhos oficiais e ação na notificação são alternativas compatíveis. O SOS nativo permanece intacto.</p></div></div>`}
function locations(){const d=activeDevice(state),positions=state.locations.filter(p=>p.deviceId===d.id);return `<div class="card"><div class="card-head"><h3>${esc(d.name)}</h3><span class="badge">${d.online?'ONLINE FICTÍCIO':'OFFLINE FICTÍCIO'}</span></div>${map(d)}<div class="actions"><button class="primary" data-action="position" ${d.online?'':'disabled'}>Atualizar posição simulada</button><button class="outline" data-action="online">Simular ${d.online?'offline':'online'}</button></div><p class="fine" style="margin-top:18px">Quando offline, a última posição fica disponível. GPS não funciona após desligamento; redes Buscar/Find Hub dependem de hardware e configuração próprios.</p></div><div class="card"><h3>Histórico fictício.</h3><label class="check"><input type="checkbox" data-privacy="history" ${state.privacy.history?'checked':''}>Guardar próximas posições fictícias</label><label class="check"><input type="checkbox" data-privacy="sharing" ${state.privacy.sharing?'checked':''}>Autorizar compartilhamento simulado</label><p class="fine">${state.privacy.sharing?'Compartilhamento fictício autorizado; nenhum link real é criado.':'Compartilhamento desativado.'}</p>${positions.map(p=>`<div class="item row"><div><strong>${esc(p.label)}</strong><small>${p.latitude.toFixed(6)}, ${p.longitude.toFixed(6)} · ±${p.accuracy} m</small></div><small>${esc(date(p.at))}</small></div>`).join('')}</div>`}
function lost(){const d=activeDevice(state);return `<div class="split"><div><div class="card"><h3>Uma mensagem de retorno.</h3><form id="lostForm"><label for="lostMessage">Mensagem fictícia do proprietário</label><textarea id="lostMessage" maxlength="180" required>${esc(d.message)}</textarea><label for="lostContact">Contato fictício</label><input id="lostContact" value="${esc(d.contact)}" maxlength="40" required><div class="actions"><button class="primary">${d.state==='LOST'?'Atualizar':'Ativar'} modo perdido</button><button type="button" class="outline" data-action="end" ${isEmergency(d)?'':'disabled'}>Desativar modo perdido</button></div></form><div class="actions"><button class="outline" data-action="alarm">Ouvir alarme demonstrativo</button><button class="text" data-action="silence">Interromper alarme</button></div><p class="fine" style="margin-top:18px">O áudio somente começa depois de ação explícita e para automaticamente após oito segundos. A tela nativa do celular nunca é substituída.</p></div></div><div>${phone(d,true)}</div></div>`}
function contacts(){return `<div class="grid"><div class="card"><div class="card-head"><h3>Pessoas autorizadas.</h3><button class="outline" data-action="newContact" ${state.contacts.length>=10?'disabled':''}>Adicionar</button></div>${state.contacts.length?state.contacts.map(c=>`<div class="item"><div class="row"><div><strong>${esc(c.name)}</strong><small>${esc(c.phone)}<br>Alertas ${c.allowAlerts?'autorizados':'não autorizados'}</small></div><span class="tag">${c.verified?'VALIDAÇÃO SIMULADA':'PENDENTE'}</span></div><div class="actions"><button class="quiet" data-edit-contact="${esc(c.id)}">Editar</button><button class="quiet" data-verify-contact="${esc(c.id)}">Simular validação</button><button class="quiet" data-alert="${esc(c.id)}" ${c.verified&&c.allowAlerts?'':'disabled'}>Simular alerta</button><button class="quiet" data-primary-contact="${esc(c.id)}">${c.primary?'Contato principal':'Definir principal'}</button><button class="quiet red" data-delete-contact="${esc(c.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Sua rede está vazia. Adicione um contato fictício.</div>'}</div><div class="card soft"><h3>Confiança começa com consentimento.</h3><p>Os contatos desta experiência são fictícios. Uma validação simulada não comprova posse de um número real.</p><p class="fine">Um alerta só pode ser simulado para um contato validado e com recebimento autorizado. Nenhum SMS, e-mail ou push é enviado.</p><button class="outline" data-action="notices">Ver alertas demonstrativos ↗</button></div></div>`}
function recovery(){const r=state.recovery,stage=r.stage;return `<div class="grid"><div class="card"><h3>Escolha como voltar.</h3><p class="fine">Métodos representados visualmente. Nenhum dado biométrico ou conta real é acessado.</p>${[['EMAIL','E-mail verificado'],['PHONE','Número principal'],['TRUSTED','Pessoa de confiança'],['BIOMETRIC','Biometria / Face ID'],['VOICE','Voz demonstrativa']].map(([id,name])=>`<label class="item check"><input type="radio" name="method" value="${id}" ${r.method===id?'checked':''}>${name}</label>`).join('')}<div class="actions"><button class="primary" data-action="recoveryStart">Iniciar recuperação demonstrativa</button></div><p class="fine" style="margin-top:18px">Voz isolada não libera acesso. O PIN e as proteções nativas do sistema são preservados.</p></div><div class="card soft"><div class="steps">${[1,2,3].map(i=>`<span class="${stage>=i?'on':''}"></span>`).join('')}</div>${stage===0?'<h2>Um passo de cada vez.</h2><p>Escolha um método para iniciar a recuperação fictícia.</p>':stage===1?`<span class="badge">ETAPA 1 / 2 · DEMO</span><h2 style="margin-top:20px">Identidade <em>reconhecida.</em></h2><p>${r.method==='VOICE'?'O reconhecimento por voz é apenas ilustrativo e exige uma segunda etapa.':r.method==='BIOMETRIC'?'A biometria é uma representação visual, sem ler Face ID ou impressão digital.':'O método selecionado foi simulado. Nenhuma mensagem foi enviada.'}</p><button class="primary" data-action="recoveryNext">Continuar verificação simulada ↗</button>`:stage===2?`<span class="badge">ETAPA 2 / 2 · DEMO</span><h2 style="margin-top:20px">Confirme sua <em>intenção.</em></h2><form id="recoveryConfirm"><label class="check"><input type="checkbox" required>Entendi que esta verificação e a recuperação são simuladas.</label><div class="actions"><button class="primary">Concluir recuperação demonstrativa</button></div></form>`:`<span class="badge">CONFIRMAÇÃO SIMULADA</span><h2 style="margin-top:20px">Controle <em>retomado.</em></h2><p>A emergência fictícia foi encerrada. A configuração de proteção foi preservada.</p><button class="outline" data-action="recoveryAgain">Explorar outro método</button>`}</div></div>`}
function plans(){return `<div class="card"><h3>Histórico de operações simuladas.</h3>${logHTML(state.billing.history,'Sem operações. Selecione um plano para testar; nenhum pagamento real é processado.')}</div><div class="card soft"><div class="row wrap"><div><h3>Sua assinatura demonstrativa.</h3><p class="fine" style="margin:0">${esc(plan().name)} · ${state.billing.period==='MONTHLY'?'Mensal':'Anual'} · ${esc({ACTIVE:'Ativa na simulação',CANCELLED:'Cancelada na simulação',PREVIEW:'Em exploração'}[state.billing.status])}<br>${state.billing.renewals} renovações simuladas · Sem pagamentos</p></div><div class="toggle"><button data-period="MONTHLY" class="${state.billing.period==='MONTHLY'?'active':''}">Mensal</button><button data-period="ANNUAL" class="${state.billing.period==='ANNUAL'?'active':''}">Anual</button></div></div><div class="actions"><button class="outline" data-action="renewPlan">Simular renovação</button><button class="text" data-action="cancelPlan">Simular cancelamento</button></div></div><div class="grid-three plans">${PLANS.map((p,i)=>`<article class="card plan ${p.id===state.billing.plan?'selected':''}"><span class="badge">${i===1?'PROTEÇÃO EM DESTAQUE':`0${i+1}`}</span><h3>${p.name}</h3><span class="price">Valor em definição</span><p class="fine">Ciclo ${state.billing.period==='MONTHLY'?'mensal':'anual'} demonstrativo</p><ul><li>${p.limit===1?'1 dispositivo fictício':'Até 5 dispositivos fictícios'}</li><li>Painel de recuperação e histórico</li><li>Comandos, contatos e localização simulados</li><li>${i===2?'Visão familiar demonstrativa':'Experiência individual'}</li></ul><button class="${i===1?'primary':'outline'}" data-plan="${p.id}">${p.id===state.billing.plan?'Explorar seleção':'Selecionar plano'} ↗</button></article>`).join('')}</div><p class="fine">Recursos reais dependem da plataforma e de permissões. Cancelar ou renovar a assinatura nunca encerra uma emergência nem desbloqueia um aparelho.</p>`}
function profile(){return `<div class="card"><h3>Segurança e privacidade.</h3><p>Sessão local DEMO · Nenhuma credencial ou biometria armazenada.</p><div class="actions"><button class="outline" data-extra="export">Exportar dados fictícios</button><button class="outline" data-extra="deleteData">Excluir dados locais</button><button class="outline" data-page="onboarding">Revisar configuração inicial</button></div></div><div class="grid"><div class="card"><h3>Informações demonstrativas.</h3><form id="profileForm"><label for="profileName">Nome fictício</label><input id="profileName" value="${esc(state.profile.name)}" maxlength="60" required><label for="profileEmail">E-mail fictício</label><input id="profileEmail" type="email" value="${esc(state.profile.email)}" maxlength="100" required><label for="profilePhone">Telefone fictício</label><input id="profilePhone" value="${esc(state.profile.phone)}" maxlength="30" required><div class="actions"><button class="primary">Salvar perfil demonstrativo</button></div></form></div><div class="card soft"><h3>Preferências.</h3><label class="check item"><input type="checkbox" data-preference="notifications" ${state.preferences.notifications?'checked':''}>Mostrar notificações demonstrativas</label><label class="check item"><input type="checkbox" data-preference="quiet" ${state.preferences.quiet?'checked':''}>Preferir fluxo visual silencioso</label><p class="fine">Estas preferências afetam apenas a demonstração. O alarme exige sempre uma ação explícita.</p><div class="actions"><button class="outline" data-action="notices">Consultar notificações</button><button class="outline" data-action="restore">Restaurar dados de demonstração</button><button class="text" data-action="logout">Sair da demonstração</button></div><p class="fine" style="margin-top:20px">Fechar o navegador preserva os dados, se o armazenamento local estiver disponível. Sair mantém suas escolhas para o próximo acesso.</p></div></div>`}
function web(){const d=activeDevice(state),tabs=[['overview','Visão geral'],['devices','Dispositivos'],['incidents','Incidentes'],['location','Mapa'],['commands','Comandos'],['activity','Atividade']];let body='';if(webTab==='overview')body=`<div class="grid"><div class="card"><h3>${esc(d.name)}</h3>${map(d)}</div><div class="card soft"><h3>Controle remoto fictício.</h3>${statusHTML(d)}<p class="fine" style="margin-top:15px">${d.online?'Online fictício':'Offline fictício; comandos aguardam reconexão'}</p><div class="actions">${Object.entries(commandNames).map(([type,name])=>`<button class="outline" data-remote="${type}">${name}</button>`).join('')}</div><p class="fine" style="margin-top:20px">Comandos ficam na fila até você executar o retorno demonstrativo. Nenhuma ação é enviada a um celular real.</p></div></div>`;
if(webTab==='devices')body=`<div class="card"><div class="card-head"><h3>Dispositivos fictícios.</h3><button class="outline" data-action="addDevice" ${state.devices.length>=plan().limit?'disabled':''}>Adicionar dispositivo</button></div><p class="fine">Plano ${esc(plan().name)} · Limite ${plan().limit}. Selecione Família para explorar mais aparelhos.</p>${state.devices.map(x=>`<div class="device-mini"><div class="row"><div><strong>${esc(x.name)}</strong><br><small>${x.platform} · ${x.online?'Online':'Offline'} fictício</small></div>${statusHTML(x)}</div><div class="actions"><button class="outline" data-select-device="${x.id}">Selecionar</button><button class="quiet" data-delete-device="${x.id}" ${state.devices.length>1?'':'disabled'}>Remover fictício</button></div></div>`).join('')}</div>`;
if(webTab==='incidents')body=`<div class="card"><h3>Incidentes demonstrativos.</h3>${logHTML(state.incidents,'Nenhum incidente. Teste uma emergência fictícia.')}</div>`;
if(webTab==='location')body=locations();
if(webTab==='commands')body=`<div class="card"><h3>Fila e confirmações demonstrativas.</h3><p class="fine">Enfileirar não significa executar. O retorno abaixo é uma simulação explícita.</p>${state.remote.length?state.remote.map(r=>{const target=state.devices.find(d=>d.id===r.deviceId);return `<div class="item"><div class="row"><div><strong>${esc(commandNames[r.type])}</strong><small>${esc(target?.name||'Dispositivo removido')} · ${esc(date(r.at))}</small></div><span class="tag">${r.status==='QUEUED'?'NA FILA':'RESULTADO SIMULADO'}</span></div><div class="actions"><button class="outline" data-apply-remote="${r.id}" ${r.status==='QUEUED'&&target?.online?'':'disabled'}>Simular retorno do aparelho</button></div>${!target?.online&&r.status==='QUEUED'?'<p class="fine">O dispositivo fictício está offline ou foi removido.</p>':''}</div>`}).join(''):'<div class="empty">Nenhum comando. Use a visão geral para criar uma solicitação fictícia.</div>'}</div>`;
if(webTab==='activity')body=`<div class="card"><h3>Trilha de atividade.</h3>${logHTML(state.activity)}</div>`;return `<div class="pillset">${tabs.map(([k,name])=>`<button data-web-tab="${k}" class="${webTab===k?'active':''}">${name}</button>`).join('')}</div>${body}`}
function render(){const d=activeDevice(state);$('#app').hidden=!state.session;$('#welcome').hidden=state.session;$('#noticeCount').textContent=state.preferences.notifications?state.notifications.filter(n=>!n.read).length:0;$('#notifications').setAttribute('aria-label',`Abrir notificações demonstrativas (${state.notifications.filter(n=>!n.read).length})`);if(!state.session){$('#welcome').innerHTML=`<div class="eyebrow">SENTINELA / DEMONSTRAÇÃO</div><h1>Entre para<br><em>explorar com calma.</em></h1><p>Uma experiência completa, sem cadastro, senha ou dados reais. Suas alterações demonstrativas foram preservadas.</p><div class="actions"><button class="primary" data-action="login">Entrar na demonstração ↗</button><a class="outline" href="./panel.html">Acessar conta real</a></div>`;return}$('#name').textContent=state.profile.name;$('#initial').textContent=state.profile.name[0]?.toUpperCase()||'A';$('#device').innerHTML=state.devices.map(d=>`<option value="${d.id}" ${d.id===state.selectedDevice?'selected':''}>${esc(d.name)}</option>`).join('');$('#nav').innerHTML=Object.entries(pages).map(([k,v],i)=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}><span>${['◈','≋','◉','⌖','⌑','♧','◎','▣','▤','◇','○','✓','▣','≡','◌','?'][i]}</span><span>${v[0]}</span></button>`).join('');$('#title').innerHTML=pages[page][1];$('#description').textContent=pages[page][2];$('#state').textContent=labels[d.state];$('#state').className='badge'+(isEmergency(d)?' alert':'');$('#view').innerHTML=({dashboard,voice,physical,location:locations,lost,contacts,recovery,web,plans,profile,onboarding,protection,devices,incidents,notifications,help}[page])();$('#bottomNav').innerHTML=[['dashboard','Início'],['protection','Proteção'],['location','Localização'],['devices','Aparelhos']].map(([k,t])=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${t}</button>`).join('');bindForms()}
function bindForms(){if($('#voiceAdd'))$('#voiceAdd').onsubmit=e=>{e.preventDefault();if(state.commands.length>=10)return toast('Limite de dez frases.');act({type:'VOICE_SAVE',phrase:$('#voicePhrase').value});toast('Comando salvo na demonstração.')};if($('#voiceTest'))$('#voiceTest').onsubmit=e=>{e.preventDefault();const phrase=state.commands.find(v=>v.id===state.selectedCommand)?.phrase||'',heard=$('#heard').value;if(matchVoice(heard,phrase,state.sensitivity)){$('#wave').classList.add('play');toast(`Reconhecimento simulado: “${phrase}”. Nenhum microfone foi aberto.`);voiceTimer=setTimeout(()=>{voiceTimer=null;if(!state.session)return;go('dashboard');simulate('Voz demonstrativa')},650)}else toast('A frase não corresponde. Nenhuma emergência foi iniciada.')};if($('#lostForm'))$('#lostForm').onsubmit=e=>{e.preventDefault();stopSimulation();act({type:'LOST',message:$('#lostMessage').value,contact:$('#lostContact').value});toast('Modo perdido atualizado no dispositivo fictício.')};if($('#recoveryConfirm'))$('#recoveryConfirm').onsubmit=e=>{e.preventDefault();stopAlarm(false);stopSimulation();act({type:'RECOVERY_COMPLETE'});toast('Recuperação simulada concluída.')};if($('#profileForm'))$('#profileForm').onsubmit=e=>{e.preventDefault();act({type:'PROFILE',name:$('#profileName').value,email:$('#profileEmail').value,phone:$('#profilePhone').value});toast('Perfil demonstrativo salvo.')};if($('#sensitivity'))$('#sensitivity').onchange=e=>act({type:'SENSITIVITY',value:e.target.value})}
function simulate(trigger='Botão demonstrativo',deviceId=state.selectedDevice){if(simulating)return toast('A simulação já está em andamento.');const d=state.devices.find(d=>d.id===deviceId);if(!d)return;act({type:'EMERGENCY',trigger,deviceId});let i=state.incidents.find(i=>i.deviceId===deviceId&&!i.closedAt);if(!i)return;if(i.step>=6)return toast('Protocolo já concluído. Encerre ou reinicie a simulação.');simulating=true;render();simulationTimer=setInterval(()=>{const incident=state.incidents.find(i=>i.deviceId===deviceId&&!i.closedAt);if(!incident){stopSimulation();return}const step=incident.step+1;act({type:'EMERGENCY_STEP',step,deviceId});if(step>=6){stopSimulation();render();toast('Bloqueio e alerta simulados. Painel fictício atualizado.')}},650)}
function stopAlarm(record=true){let wasPlaying=!!alarm;if(alarm){try{alarm.stop()}catch{}alarm=null}if(alarmContext){alarmContext.close().catch(()=>{});alarmContext=null}clearTimeout(alarmTimeout);if(wasPlaying&&record){act({type:'ALARM_LOG',playing:false});toast('Alarme demonstrativo interrompido.')}}
function startAlarm(){stopAlarm(false);try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return toast('Este navegador não disponibiliza áudio.');alarmContext=new Audio();alarm=alarmContext.createOscillator();const gain=alarmContext.createGain();gain.gain.value=.035;alarm.frequency.value=660;alarm.type='sine';alarm.connect(gain).connect(alarmContext.destination);alarm.start();act({type:'ALARM_LOG',playing:true});toast('Alarme demonstrativo tocando. Use Interromper ou aguarde oito segundos.');alarmTimeout=setTimeout(()=>stopAlarm(),8000)}catch{stopAlarm(false);toast('O navegador não permitiu iniciar o áudio.')}}
function confirm(title,text,callback,label='Confirmar'){modal(`<div class="eyebrow">APENAS DEMONSTRAÇÃO</div><h2>${title}</h2><p>${text}</p><div class="actions"><button class="primary" id="confirmAction">${label}</button><button class="outline" id="cancelAction">Voltar</button></div>`);$('#confirmAction').onclick=()=>{close();callback()};$('#cancelAction').onclick=close}
function restore(){confirm('Um novo <em>começo.</em>','Isso restaura somente os dados fictícios desta demonstração. Nenhuma conta ou configuração real é alterada.',()=>{stopSimulation();stopAlarm(false);state=initial();page='dashboard';webTab='overview';save();render();toast('Dados de demonstração restaurados. Permanece tudo fictício.')},'Restaurar dados de demonstração')}
function editVoice(id){const v=state.commands.find(v=>v.id===id);if(!v)return;modal(`<div class="eyebrow">COMANDO DEMONSTRATIVO</div><h2>Edite sua <em>frase.</em></h2><form id="voiceEdit"><label for="editedPhrase">Frase</label><input id="editedPhrase" value="${esc(v.phrase)}" maxlength="50" required><div class="actions"><button class="primary">Salvar comando</button></div></form>`);$('#voiceEdit').onsubmit=e=>{e.preventDefault();act({type:'VOICE_SAVE',id,phrase:$('#editedPhrase').value});close();toast('Frase atualizada na demonstração.')}}
function editContact(id){const c=state.contacts.find(c=>c.id===id);modal(`<div class="eyebrow">SUA REDE FICTÍCIA</div><h2>${c?'Editar':'Adicionar'} <em>contato.</em></h2><form id="contactEdit"><label for="contactName">Nome fictício</label><input id="contactName" value="${esc(c?.name||'')}" required maxlength="60"><label for="contactPhone">Número fictício</label><input id="contactPhone" value="${esc(c?.phone||'(00) 92222-2222')}" required maxlength="30"><label class="check"><input id="contactAlerts" type="checkbox" ${c?.allowAlerts?'checked':''}>Autorizar alertas demonstrativos para este contato fictício.</label><p class="fine">Nenhuma mensagem será enviada. Alterar o número exige nova validação simulada.</p><div class="actions"><button class="primary">Salvar contato</button></div></form>`);$('#contactEdit').onsubmit=e=>{e.preventDefault();act({type:'CONTACT_SAVE',id,name:$('#contactName').value,phone:$('#contactPhone').value,allowAlerts:$('#contactAlerts').checked});close();toast('Contato fictício salvo.')}}
function showNotices(){modal(`<div class="eyebrow">SEM ENTREGA EXTERNA</div><h2>Notificações <em>demonstrativas.</em></h2>${state.notifications.length?state.notifications.map(n=>`<div class="item"><strong>${esc(n.text)}</strong><small>${esc(date(n.at))}</small></div>`).join(''):'<p>Nenhuma notificação. Explore uma emergência ou um alerta fictício.</p>'}`);act({type:'READ_NOTICES'})}
function selectPlan(id){const p=PLANS.find(p=>p.id===id);act({type:'PLAN',plan:id});modal(`<div class="eyebrow">CONTRATAÇÃO SIMULADA</div><h2>${esc(p.name)}.</h2><div class="item row"><span>Ciclo</span><strong>${state.billing.period==='MONTHLY'?'Mensal':'Anual'}</strong></div><div class="item row"><span>Preço</span><strong>Em definição</strong></div><p class="fine" style="margin-top:20px">Não há cobrança, dados bancários ou assinatura real. Os recursos nativos dependem de plataforma e permissões.</p><form id="planConfirm"><label class="check"><input type="checkbox" required>Entendi que a contratação é apenas demonstrativa.</label><div class="actions"><button class="primary">Confirmar contratação simulada</button></div></form>`);$('#planConfirm').onsubmit=e=>{e.preventDefault();act({type:'PLAN_CONFIRM'});close();toast('Contratação simulada confirmada. Nenhuma cobrança.')}}
function addDevice(){if(state.devices.length>=plan().limit)return toast('Selecione o plano Família para adicionar dispositivos fictícios.');modal(`<div class="eyebrow">DISPOSITIVO DEMONSTRATIVO</div><h2>Mais um <em>cuidado.</em></h2><form id="deviceAdd"><label for="deviceName">Nome fictício</label><input id="deviceName" value="Celular da família" maxlength="60" required><label for="devicePlatform">Plataforma ilustrativa</label><select id="devicePlatform"><option value="ANDROID">Android</option><option value="IOS">iPhone</option></select><p class="fine">Não há pareamento, credencial ou dispositivo real.</p><div class="actions"><button class="primary">Adicionar dispositivo fictício</button></div></form>`);$('#deviceAdd').onsubmit=e=>{e.preventDefault();act({type:'DEVICE_ADD',name:$('#deviceName').value,platform:$('#devicePlatform').value});close();toast('Dispositivo fictício adicionado.')}}
function remote(type){confirm(`${esc(commandNames[type])} <em>na demonstração.</em>`,type==='ALARM'?'Este comando será apenas enfileirado. Para ouvir um alarme demonstrativo, você precisará autorizar o áudio ao executar o retorno.':'A ação será adicionada à fila do painel fictício. Nenhuma API, conta real ou aparelho externo será acessado.',()=>{act({type:'REMOTE',command:type});webTab='commands';render();toast('Comando fictício na fila. Simule o retorno para concluir.')},'Enfileirar comando fictício')}
function applyRemote(id){const r=state.remote.find(r=>r.id===id),d=r?state.devices.find(d=>d.id===r.deviceId):null;if(!r||!d?.online)return toast('O dispositivo fictício precisa estar online.');if(r.type==='ALARM')return confirm('Ouvir um <em>alarme demonstrativo?</em>','A ação seguinte reproduzirá áudio neste navegador por até oito segundos. Não será acionado um telefone real.',()=>{act({type:'REMOTE_APPLY',id});startAlarm()},'Autorizar áudio e simular retorno');if(r.type==='STOP_ALARM')stopAlarm(false);act({type:'REMOTE_APPLY',id});toast('Resultado do comando simulado. Nenhuma operação real foi executada.')}
function action(name){const d=activeDevice(state);if(name==='login'){act({type:'SESSION',active:true});go('dashboard')}if(name==='logout'){stopSimulation();stopAlarm(false);act({type:'SESSION',active:false});$('#app aside').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}if(name==='protection'){act({type:'PROTECTION',active:!d.protected});toast('Preferência de proteção demonstrativa atualizada.')}if(name==='emergency')simulate();if(name==='end'){stopSimulation();stopAlarm(false);act({type:'END'});toast('Estado de emergência fictício encerrado.')}if(name==='resetDevice'){stopSimulation();stopAlarm(false);act({type:'RESET_DEVICE'});toast('Simulação reiniciada. Seu histórico foi preservado.')}if(name==='position'){if(!d.online)return toast('Dispositivo fictício offline.');act({type:'POSITION'});toast('Posição fictícia atualizada.')}if(name==='online')act({type:'ONLINE',online:!d.online});if(name==='animateSequence'){const el=$('#sequence');el.classList.remove('play');void el.offsetWidth;el.classList.add('play');toast('Animação da sequência; botões reais não são interceptados.')}if(name==='saveSequence'){save();toast('Sequência demonstrativa salva neste navegador.')}if(name==='sequenceEmergency'){go('dashboard');simulate('Sequência física demonstrativa')}if(name==='marker')toast(`${d.name} · posição fictícia · nenhum GPS acessado.`);if(name==='zoomIn'||name==='zoomOut'){zoom=Math.max(.7,Math.min(1.8,zoom+(name==='zoomIn'?.2:-.2)));render()}if(name==='centerMap'){zoom=1;render();toast('Mapa fictício centralizado.')}if(name==='alarm')startAlarm();if(name==='silence')stopAlarm();if(name==='found')toast('Obrigado! Este contato e este aparelho são fictícios; nenhuma ligação será feita.');if(name==='newContact')editContact();if(name==='recoveryStart'){stopSimulation();const method=$('input[name=method]:checked')?.value||state.recovery.method;act({type:'RECOVERY_START',method})}if(name==='recoveryNext')act({type:'RECOVERY_STEP'});if(name==='recoveryAgain'){state.recovery.stage=0;save();render()}if(name==='notices')showNotices();if(name==='restore')restore();if(name==='renewPlan'){act({type:'PLAN_RENEW'});toast('Renovação simulada. Nenhuma cobrança.')}if(name==='cancelPlan')confirm('Cancelar a <em>simulação da assinatura?</em>','A assinatura fictícia será cancelada. A proteção e qualquer emergência continuarão no mesmo estado.',()=>{act({type:'PLAN_CANCEL'});toast('Assinatura cancelada apenas na demonstração.')});if(name==='addDevice')addDevice()}
$('#menu').onclick=()=>{if(!state.session)return toast('Entre na demonstração para abrir o menu.');const open=$('#app aside').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#restore').onclick=restore;$('#notifications').onclick=showNotices;$('#device').onchange=e=>act({type:'SELECT_DEVICE',id:e.target.value});
document.addEventListener('click',e=>{const b=e.target.closest('[data-page],[data-action],[data-edit-voice],[data-delete-voice],[data-edit-contact],[data-delete-contact],[data-verify-contact],[data-alert],[data-period],[data-plan],[data-web-tab],[data-remote],[data-apply-remote],[data-select-device],[data-delete-device]');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.action)action(b.dataset.action);if(b.dataset.editVoice)editVoice(b.dataset.editVoice);if(b.dataset.deleteVoice)confirm('Excluir o <em>comando?</em>','Apenas a frase demonstrativa será removida.',()=>act({type:'VOICE_DELETE',id:b.dataset.deleteVoice}));if(b.dataset.editContact)editContact(b.dataset.editContact);if(b.dataset.deleteContact)confirm('Remover o <em>contato fictício?</em>','Esta ação afeta somente os dados locais da demonstração.',()=>act({type:'CONTACT_DELETE',id:b.dataset.deleteContact}));if(b.dataset.verifyContact){act({type:'CONTACT_VERIFY',id:b.dataset.verifyContact});toast('Validação simulada. Nenhum código ou SMS foi enviado.')}if(b.dataset.alert){act({type:'ALERT',id:b.dataset.alert});toast('Alerta fictício registrado. Nenhuma mensagem enviada.')}if(b.dataset.period)act({type:'PERIOD',period:b.dataset.period});if(b.dataset.plan)selectPlan(b.dataset.plan);if(b.dataset.webTab){webTab=b.dataset.webTab;render()}if(b.dataset.remote)remote(b.dataset.remote);if(b.dataset.applyRemote)applyRemote(b.dataset.applyRemote);if(b.dataset.selectDevice)act({type:'SELECT_DEVICE',id:b.dataset.selectDevice});if(b.dataset.deleteDevice)confirm('Remover o <em>aparelho fictício?</em>','Não afeta nenhum dispositivo real. O último aparelho fictício sempre é mantido.',()=>act({type:'DEVICE_DELETE',deviceId:b.dataset.deleteDevice}))});
document.addEventListener('change',e=>{if(e.target.dataset.voiceSelect)act({type:'VOICE_SELECT',id:e.target.dataset.voiceSelect});if(e.target.dataset.sequence)act({type:'SEQUENCE',id:e.target.dataset.sequence});if(e.target.dataset.preference)act({type:'PREFERENCE',key:e.target.dataset.preference,value:e.target.checked})});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAlarm(false)});window.addEventListener('pagehide',()=>{stopAlarm(false);stopSimulation();save()});window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]){page=p;render()}});render();

function permissions(d){return Object.entries({location:'Localização pontual',microphone:'Microfone em sessão explícita',admin:'Administração / bloqueio autorizado',notifications:'Notificações'}).map(([key,label])=>`<label class="check item"><input type="checkbox" data-permission="${key}" ${d.permissions[key]?'checked':''}>${label}<span class="tag">FICTÍCIO</span></label>`).join('')}
function onboarding(){const steps=[['Boas-vindas','Explore todas as áreas sem cadastro. Esta demonstração funciona offline e nunca usa APIs reais.'],['Como funciona a proteção','Proteção ativa reúne configuração, sincronização e ações consentidas. O Android mantém o controle do PIN e das chamadas de emergência.'],['Permissões','As opções abaixo representam permissões. No aplicativo real, cada autorização exige os diálogos oficiais do Android.'],['Seu dispositivo','Renomeie o aparelho fictício em Dispositivos. O cadastro real é autenticado e usa uma credencial exclusiva.'],['Sua rede de confiança','Cadastre um contato fictício, simule verificação e autorize alertas. Nenhuma mensagem será enviada.'],['Biometria e recuperação','Biometria é simulada aqui. No Android real depende de hardware e cadastro no sistema. Recuperação nunca remove o PIN.'],['Tudo pronto','Configuração demonstrativa concluída. Você pode revisar as escolhas a qualquer momento.']],n=state.onboarding.step,[title,text]=steps[n];return `<div class="card onboarding"><span class="badge">PASSO ${n+1} DE 7 · DEMO</span><div class="steps">${steps.map((_,i)=>`<span class="${i<=n?'on':''}"></span>`).join('')}</div><h2>${title}</h2><p>${text}</p>${n===2?permissions(activeDevice(state)):''}${n===3?`<p><strong>${esc(activeDevice(state).name)}</strong></p><button class="outline" data-page="devices">Configurar aparelho</button>`:''}${n===4?'<button class="outline" data-page="contacts">Gerenciar contatos</button>':''}${n===5?'<button class="outline" data-page="recovery">Testar recuperação</button>':''}<div class="actions">${n>0?`<button class="outline" data-onboarding="${n-1}">Voltar</button>`:''}${n<6?`<button class="primary" data-onboarding="${n+1}">Continuar</button>`:'<button class="primary" data-page="dashboard">Ir para o início</button>'}</div></div>`}
function protection(){const d=activeDevice(state);return `<div class="grid"><div class="card soft"><div class="card-head"><h3>${esc(d.name)}</h3>${statusHTML(d)}</div><p>Proteção ${d.protected?'ativada':'desativada'} na simulação. Nenhum comando de bloqueio real é executado.</p><button class="primary" data-action="protection" ${isEmergency(d)?'disabled':''}>${d.protected?'Desativar':'Ativar'} proteção fictícia</button><label for="level">Nível demonstrativo</label><select id="level" data-setting="level">${[['ESSENTIAL','Essencial'],['BALANCED','Equilibrado'],['STRICT','Reforçado']].map(([k,t])=>`<option value="${k}" ${state.level===k?'selected':''}>${t}</option>`).join('')}</select><p class="fine">O nível registra uma preferência; não amplia privilégios Android.</p><div class="actions"><button class="outline" data-action="emergency">Testar bloqueio simulado</button><button class="outline" data-page="incidents">Consultar histórico</button></div></div><div class="card"><h3>Diagnóstico de permissões fictícias.</h3>${permissions(d)}<p class="fine">${Object.values(d.permissions).filter(Boolean).length} de 4 permissões fictícias ativas. Ajustar aqui não concede acesso ao navegador.</p></div></div><div class="card"><h3>Mecanismos e compatibilidade.</h3><div class="item"><strong>Bloqueio autorizado</strong><p>Android: DevicePolicyManager, quando configurado. Nunca impede desligamento nem chamadas de emergência.</p></div><div class="item"><strong>Voz e localização</strong><p>Sessões explícitas, limitadas por permissão e disponibilidade. Não há microfone permanente ou GPS após desligar.</p></div><div class="item"><strong>Botões físicos</strong><p>Power triplo e Power + Volume são apenas simulações; não substituem o SOS nativo. O aplicativo e a notificação oferecem atalhos compatíveis.</p></div></div>`}
function devices(){return `<div class="card"><div class="card-head"><h3>Meus aparelhos fictícios.</h3><button class="outline" data-action="addDevice" ${state.devices.length>=plan().limit?'disabled':''}>Adicionar</button></div><p class="fine">${state.devices.length}/${plan().limit} dispositivos · Plano ${esc(plan().name)}. Para vários aparelhos, selecione Família.</p>${state.devices.map(d=>`<div class="device-mini"><div class="row wrap"><div><strong>${esc(d.name)}</strong><small>${d.platform} · ${d.revoked?'Autorização revogada':d.online?'Online fictício':'Offline fictício'}<br>Última sincronização fictícia ${date(d.lastSync)}</small></div>${statusHTML(d)}</div><div class="actions"><button class="outline" data-device-detail="${d.id}">Detalhes</button><button class="outline" data-select-device="${d.id}">${state.selectedDevice===d.id?'Selecionado':'Selecionar'}</button><button class="quiet" data-rename-device="${d.id}">Renomear</button><button class="quiet red" data-revoke-device="${d.id}" ${d.revoked?'disabled':''}>Revogar autorização</button><button class="quiet red" data-delete-device="${d.id}" ${state.devices.length===1?'disabled':''}>Remover</button></div></div>`).join('')}</div>`}
function incidents(){const filtered=state.incidents.filter(i=>incidentFilter==='ALL'||incidentFilter==='OPEN'&&!i.closedAt||incidentFilter==='CLOSED'&&i.closedAt||i.type===incidentFilter);return `<div class="card"><div class="card-head"><h3>Incidentes demonstrativos.</h3><span class="badge">${filtered.length} REGISTROS</span></div><label for="incidentFilter">Filtrar incidentes</label><select id="incidentFilter" data-setting="incidentFilter">${[['ALL','Todos'],['OPEN','Em andamento'],['CLOSED','Encerrados'],['EMERGENCY','Emergência'],['LOST','Modo perdido']].map(([k,t])=>`<option value="${k}" ${incidentFilter===k?'selected':''}>${t}</option>`).join('')}</select>${filtered.length?filtered.map(i=>`<div class="item row wrap"><div><strong>${esc(i.trigger)}</strong><small>${date(i.at)} · ${i.closedAt?'Encerrado':'Em andamento'}<br>${esc(state.devices.find(d=>d.id===i.deviceId)?.name||i.deviceName||'Aparelho removido')}</small></div><button class="outline" data-incident="${i.id}">Ver detalhes</button></div>`).join(''):'<div class="empty">Nenhum incidente neste filtro. Simule uma emergência para explorar o histórico.</div>'}</div>`}
function notifications(){return `<div class="card"><div class="card-head"><h3>Central de notificações.</h3><button class="outline" data-extra="readAll">Marcar todas como lidas</button></div><label class="check"><input type="checkbox" data-preference="notifications" ${state.preferences.notifications?'checked':''}>Mostrar contador de alertas locais</label>${state.notifications.length?state.notifications.map(n=>`<div class="item"><strong>${esc(n.text)}</strong><small>${date(n.at)} · ${n.read?'Lida':'Não lida'} · Entrega simulada</small><div class="actions"><button class="quiet" data-read-notice="${n.id}" ${n.read?'disabled':''}>Marcar como lida</button><button class="quiet" data-delete-notice="${n.id}">Remover</button></div></div>`).join(''):'<div class="empty">Nenhuma notificação. Teste um alerta consentido ou o modo perdido.</div>'}</div>`}
function help(){return `<div class="grid"><div class="card"><h3>Perguntas frequentes.</h3>${[['Como configurar o Android?','No aplicativo nativo, entre na conta, cadastre o dispositivo e autorize cada recurso desejado. Administração é opcional e exclusiva do bloqueio autorizado.'],['Como funciona a localização?','A captura real é pontual e consentida. Aparelho offline mostra última posição conhecida; desligado não significa rastreamento ao vivo. Aqui todas as posições são fictícias.'],['Como recuperar o celular?','Use o painel autenticado e as etapas de recuperação. O processo encerra a emergência SENTINELA, sem eliminar PIN Android.'],['Posso usar no iPhone?','Esta demonstração web é navegável no iPhone. Não existe aplicativo iOS nativo nesta fase; APK instala somente em Android compatível.'],['O que funciona em segundo plano?','Sincronização Android usa serviço foreground iniciado pelo usuário, sujeito às restrições do sistema. Voz é uma sessão finita e explícita.'],['Como funcionam os pagamentos?','Todos os planos aqui são simulados. Não existem cobrança ou dados bancários. Billing de produção depende de configuração futura.']].map(([q,a])=>`<details class="item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="card"><h3>Diagnóstico técnico DEMO.</h3><div class="item"><strong>Armazenamento</strong><p>Preferências no navegador, chave exclusiva DEMO. Dados permanecem após reabrir quando localStorage está disponível.</p></div><div class="item"><strong>Conectividade e permissões</strong><p>Sem API, GPS, microfone, notificações externas ou bloqueio nativo. Navegação offline com assets locais.</p></div><div class="actions"><button class="outline" data-page="protection">Permissões fictícias</button><button class="outline" data-page="onboarding">Configuração inicial</button></div></div></div><div class="card"><h3>Privacidade, termos e sobre.</h3><p>SENTINELA · Desenvolvido por unitrixapp. Versão de demonstração para avaliação de experiência. Não substitui recursos de segurança nativos, serviços de emergência ou procedimentos de recuperação do fabricante.</p><p>Use somente dados fictícios. Os registros ficam neste navegador e podem ser exportados ou excluídos no perfil. Alertas, verificações e pagamentos são representações visuais. Termos e política de produção precisam de revisão antes do lançamento comercial.</p></div>`}
function deviceDetail(id){const d=state.devices.find(x=>x.id===id);if(!d)return;modal(`<span class="badge">DISPOSITIVO FICTÍCIO</span><h2>${esc(d.name)}</h2><p>${d.platform} · ${d.revoked?'Revogado':d.online?'Online':'Offline'} · ${esc(labels[d.state])}</p><p class="fine">Última atividade: ${date(d.lastSync)}<br>Permissões fictícias: ${Object.entries(d.permissions).map(([k,v])=>`${k}: ${v?'ativa':'pendente'}`).join(' · ')}</p><h3>Histórico individual</h3>${logHTML(state.incidents.filter(i=>i.deviceId===id))}<h3>Comandos fictícios</h3>${logHTML(state.remote.filter(r=>r.deviceId===id).map(r=>({...r,text:`${commandNames[r.type]} · ${r.status}`})))}`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-extra],[data-onboarding],[data-rename-device],[data-revoke-device],[data-device-detail],[data-incident],[data-read-notice],[data-delete-notice],[data-primary-contact]');if(!b)return;const x=b.dataset;if(x.onboarding!==undefined)act({type:'ONBOARDING',step:Number(x.onboarding)});if(x.deviceDetail)deviceDetail(x.deviceDetail);if(x.renameDevice){const d=state.devices.find(d=>d.id===x.renameDevice);modal(`<h2>Renomear aparelho fictício.</h2><form id="renameDevice"><label for="rename">Nome</label><input id="rename" value="${esc(d.name)}" maxlength="60" required><div class="actions"><button class="primary">Salvar nome</button></div></form>`);$('#renameDevice').onsubmit=e=>{e.preventDefault();act({type:'DEVICE_RENAME',deviceId:d.id,name:$('#rename').value});close();toast('Nome fictício atualizado.')};}if(x.revokeDevice)confirm('Revogar autorização fictícia?','Aparelho ficará offline e os comandos pendentes serão cancelados. Nenhum token real é alterado.',()=>{act({type:'DEVICE_REVOKE',deviceId:x.revokeDevice});toast('Autorização fictícia revogada.')});if(x.incident){const i=state.incidents.find(i=>i.id===x.incident),p=state.locations.find(p=>p.deviceId===i.deviceId&&p.at>=i.at);modal(`<span class="badge">EVENTO FICTÍCIO</span><h2>${esc(i.trigger)}</h2><p>${date(i.at)} · ${esc(i.type)}<br>${i.closedAt?'Encerrado em '+date(i.closedAt):'Em andamento'}</p><h3>Ações e resultados simulados</h3><p>${i.step}/6 etapas concluídas. ${i.step>=3?'Bloqueio representado visualmente.':'Nenhum bloqueio simulado concluído.'} ${i.step>=5?'Alerta fictício registrado.':'Nenhum alerta de protocolo concluído.'}</p><p>Localização: ${p?esc(p.label)+' · ±'+p.accuracy+' m · fictícia':'não associada a este incidente'}.</p><p class="fine">Nenhuma ação física ou entrega externa foi comprovada.</p>${!i.closedAt?`<button class="primary" id="closeIncident">Encerrar incidente fictício</button>`:''}`);if($('#closeIncident'))$('#closeIncident').onclick=()=>{act({type:'END',deviceId:i.deviceId});close();toast('Incidente encerrado na demonstração.')};}if(x.readNotice)act({type:'NOTICE_READ',id:x.readNotice});if(x.deleteNotice)act({type:'NOTICE_DELETE',id:x.deleteNotice});if(x.primaryContact){act({type:'CONTACT_PRIMARY',id:x.primaryContact});toast('Contato principal atualizado.')};if(x.extra==='monitor')act({type:'MONITORING',active:!state.monitoring});if(x.extra==='readAll')act({type:'READ_NOTICES'});if(x.extra==='export'){const blob=new Blob([serialize(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sentinela-dados-ficticios.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportação contém somente dados desta demonstração.')}if(x.extra==='deleteData')confirm('Excluir dados locais?','Todas as alterações fictícias deste navegador serão apagadas. Nenhuma conta real será excluída.',()=>{stopSimulation();stopAlarm(false);state=extendState(initial());state.session=false;try{localStorage.removeItem(KEY)}catch{}render();toast('Dados locais excluídos. Entre para iniciar outra demonstração.')},'Excluir dados fictícios')});
document.addEventListener('change',e=>{const x=e.target.dataset;if(x.permission){act({type:'PERMISSION',key:x.permission,value:e.target.checked});toast('Permissão fictícia atualizada; sistema real inalterado.')}if(x.privacy)act({type:'PRIVACY',key:x.privacy,value:e.target.checked});if(x.setting==='level'){act({type:'LEVEL',value:e.target.value});toast('Nível demonstrativo salvo.')}if(x.setting==='incidentFilter'){incidentFilter=e.target.value;render()}});
